using System.ComponentModel;
using Microsoft.Extensions.AI;

public class WarehouseTools
{
    [Description("Fetches current real-time inventory quantity and reserved count for a specific SKU.")]
    public static async Task<InventoryResult> GetInventoryQuantity(
        [Description("The standardized product SKU, e.g. SKU-104")] string sku,
        [Description("Warehouse regional location (e.g. Chicago, Dallas, Seattle)")] string warehouse,
        CancellationToken ct = default)
    {
        // Simulated database call
        await Task.Delay(50, ct);
        return new InventoryResult(sku, warehouse, InStock: 42, Reserved: 5);
    }

    [Description("Sends an urgent stock replenishment alert to the warehouse procurement manager.")]
    public static async Task<bool> SendRestockAlert(
        [Description("The product SKU")] string sku,
        [Description("Quantity requested to order")] int orderQuantity,
        [Description("Urgency rating")] AlertPriority priority)
    {
        // Simulated alerting logic
        return true;
    }
}

public record InventoryResult(string Sku, string Warehouse, int InStock, int Reserved);
public enum AlertPriority { Low, Medium, High, Critical }

// Register tools in ChatOptions
var tools = new List<AIFunction>
{
    AIFunctionFactory.Create(WarehouseTools.GetInventoryQuantity),
    AIFunctionFactory.Create(WarehouseTools.SendRestockAlert)
};

var options = new ChatOptions { Tools = tools };

public async Task<ChatMessage> ExecuteToolSafelyAsync(FunctionCallContent call, CancellationToken ct)
{
    try
    {
        var result = await _toolDispatcher.InvokeAsync(call.Name, call.Arguments, ct);
        return new ChatMessage(ChatRole.Tool, JsonSerializer.Serialize(result))
        {
            Contents = { new FunctionResultContent(call.CallId, result) }
        };
    }
    catch (ArgumentException ex)
    {
        // Return semantic error feedback allowing model to self-correct
        var errorMessage = $"Validation Error on tool '{call.Name}': {ex.Message}. Please correct the parameters and retry.";
        return new ChatMessage(ChatRole.Tool, errorMessage)
        {
            Contents = { new FunctionResultContent(call.CallId, errorMessage) }
        };
    }
    catch (Exception ex)
    {
        var errorNotice = $"System Error: The tool '{call.Name}' temporarily failed: {ex.Message}.";
        return new ChatMessage(ChatRole.Tool, errorNotice)
        {
            Contents = { new FunctionResultContent(call.CallId, errorNotice) }
        };
    }
}
